const fs = require("fs")
function lastLine() {
  return new Promise((resolve) => {
    let raw = ""
    const s = fs.createReadStream("chunk-log.txt", "utf8")
    s.on("data", (c) => { raw += c })
    s.on("end", () => {
      const lines = raw.trim().split(/\r?\n/)
      resolve(lines[lines.length - 1])
    })
  })
}
lastLine().then((v) => console.log(v))
module.exports = { lastLine }
